{
  "skill_id": "brainstorming",
  "required_capabilities": [
    "fs.read"
  ],
  "optional_capabilities": [
    "doc.write"
  ],
  "degrade_rules": [
    {
      "when_missing": "doc.write",
      "state": "degraded-but-supported",
      "behavior": "design may be discussed, but formal design artifact must be written later"
    }
  ]
}

{
  "skill_id": "code-reviewer",
  "required_capabilities": [
    "fs.read"
  ],
  "optional_capabilities": [
    "shell.exec",
    "diff.read",
    "security.scan"
  ],
  "degrade_rules": [
    {
      "when_missing": "diff.read",
      "state": "degraded-but-supported",
      "behavior": "review falls back to file-level analysis instead of diff-grounded review"
    }
  ]
}

{
  "skill_id": "subagent-driven-development",
  "required_capabilities": [
    "fs.read",
    "agent.spawn"
  ],
  "optional_capabilities": [
    "shell.exec",
    "test.runner"
  ],
  "degrade_rules": [
    {
      "when_missing": "agent.spawn",
      "state": "unsupported",
      "behavior": "this execution pattern cannot be claimed without subagent support"
    }
  ]
}

